mainApp.controller("karvySetupfreedemataccountController",["$scope","$rootScope","$state","serverService",function(e,n,t,o){$(".setbox").on("click",function(){return $("html, body").animate({scrollTop:0},100),!1}),e.PanVerification=function(){$("#loader-cs").show();var n=new Object,t=$("#pannumber").val();$("#email").val(),$("#mobile").val();if(!new RegExp("^([a-zA-Z]{1,3}[pP]{1,1}[a-zA-Z]{1,1}[0-9]{1,4}[a-zA-Z]{1,1})$").test(t))return $("#loader-cs").hide(),$("#lblPanValidation").text("Please enter the valid PanNumber"),$("#lblPanValidation").show(),$("#pannumber").focus(),!1;$("#lblPanValidation").hide(),n.PanNumber=t;JSON.stringify(n);var a={PanNumber:t};o.apiCall("KarvyLeadCreation",a).success(function(n){n.IsSuccess?e.DoEsign(t):($("#loader-cs").hide(),document.getElementById("panMsgPopup").style.display="block",document.getElementById("modal-backdrop").style.display="block")})},e.closeModal=function(){document.getElementById("panMsgPopup").style.display="none",document.getElementById("modal-backdrop").style.display="none"},e.closeEsignModal=function(){document.getElementById("EsignMsgPopup").style.display="none",document.getElementById("modal-backdrop").style.display="none"},e.DoEsign=function(n){$("#loader-cs").show();var t="GenerateESignPDFForLead?PanNumber="+n;o.getList(t).then(function(n){n.IsSuccess&&""!=n.requestXml?(frmMain.action=n.eSignApiUrl,$("#msg").val(n.requestXml),document.getElementById("frmMain").submit()):($("#loader-cs").hide(),e.ErrorMessage=n.ErrorMessage,document.getElementById("EsignMsgPopup").style.display="block",document.getElementById("modal-backdrop").style.display="block")})},e.redirectpage=function(){t.go("karvy")}}]);